1186:     // Filter thinking content helper
1187:     filterThinkingContent(content) {
1188:         if (!content || typeof content !== 'string') {
1189:             return content;
1190:         }
1191:         
1192:         // Check if thinking filter is enabled (default to true)
1193:         if (this.thinkingFilterEnabled === false) {
1194:             return content;
1195:         }
1196:         
1197:         // Remove content between <think> and </think> tags (case insensitive, multiline)
1198:         const thinkingRegex = /<think\s*>[\s\S]*?<\/think\s*>/gi;
1199:         const originalLength = content.length;
1200:         
1201:         // Remove thinking content but preserve surrounding whitespace structure
1202:         let filteredContent = content.replace(thinkingRegex, (match, offset, string) => {
1203:             // Check if the thinking block is on its own line(s)
1204:             const beforeMatch = string.substring(0, offset);
1205:             const afterMatch = string.substring(offset + match.length);
1206:             
1207:             const beforeEndsWithNewline = beforeMatch.endsWith('\n') || beforeMatch.endsWith('\n\n');
1208:             const afterStartsWithNewline = afterMatch.startsWith('\n') || afterMatch.startsWith('\n\n');
1209:             
1210:             // If the thinking block is on its own line, preserve one newline
1211:             if (beforeEndsWithNewline && afterStartsWithNewline) {
1212:                 return '\n';
1213:             }
1214:             // If it's inline, just remove it
1215:             return '';
1216:         });
1217:         
1218:         // Only clean up excessive newlines (3 or more consecutive), preserve normal paragraph breaks
1219:         filteredContent = filteredContent.replace(/\n{3,}/g, '\n\n');
1220:         
1221:         // Log if thinking content was filtered
1222:         if (originalLength !== filteredContent.length) {
1223:             console.log(`🧠 Filtered thinking content: ${originalLength} → ${filteredContent.length} chars`);
1224:         }
1225:         
1226:         return filteredContent;
1227:     }
