230:     _extractTextFromPDF(arrayBuffer) {
231:         // Lightweight PDF text extraction without external libraries.
232:         // Works for most text-based PDFs (not scanned images).
233:         try {
234:             const bytes = new Uint8Array(arrayBuffer);
235:             const text = new TextDecoder('utf-8', { fatal: false }).decode(bytes);
236:             
237:             // Extract text between BT...ET blocks (PDF text objects)
238:             const textBlocks = [];
239:             const btEtRegex = /BT\s([\s\S]*?)\s*ET/g;
240:             let match;
241:             
242:             while ((match = btEtRegex.exec(text)) !== null) {
243:                 const block = match[1];
244:                 // Extract text from Tj and TJ operators
245:                 const tjRegex = /\(([^)]*?)\)\s*Tj/g;
246:                 let tjMatch;
247:                 while ((tjMatch = tjRegex.exec(block)) !== null) {
248:                     textBlocks.push(tjMatch[1]);
249:                 }
250:                 // Extract from TJ arrays
251:                 const tjArrayRegex = /\[([^\]]*)\]\s*TJ/g;
252:                 let tjArrMatch;
253:                 while ((tjArrMatch = tjArrayRegex.exec(block)) !== null) {
254:                     const arrContent = tjArrMatch[1];
255:                     const strRegex = /\(([^)]*?)\)/g;
256:                     let strMatch;
257:                     while ((strMatch = strRegex.exec(arrContent)) !== null) {
258:                         textBlocks.push(strMatch[1]);
259:                     }
260:                 }
261:             }
262:             
263:             // Decode PDF escape sequences
264:             let result = textBlocks.join(' ')
265:                 .replace(/\\n/g, '\n')
266:                 .replace(/\\r/g, '')
267:                 .replace(/\\t/g, ' ')
268:                 .replace(/\\\(/g, '(')
269:                 .replace(/\\\)/g, ')')
270:                 .replace(/\\{2}/g, '\\')
271:                 .replace(/\s{3,}/g, '\n\n')
272:                 .replace(/  +/g, ' ');
273:             
274:             return result;
275:         } catch (e) {
276:             console.error('PDF extraction error:', e);
277:             return '';
278:         }
279:     }
