32:         const frameLength = Math.max(micInput.length, systemInput.length);
33:         if (frameLength === 0) return true;
34: 
35:         for (let i = 0; i < frameLength; i++) {
36:             const micSample = i < micInput.length ? micInput[i] : 0;
